) as s(slug, nausys_id) join public.yachts y on y.slug = s.slug;

-- The sample boats leave the site (rows kept until nothing refers to them).
update public.yachts set published = false where name is null;

-- Course dates sail on real boats: one course per boat, so no week is double-booked.
update public.course_dates set yacht_slug = 'beneteau-oceanis-38-solar', boat = 'Solar, Beneteau Oceanis 38' where course_slug = 'introduction-to-yachting' and boat <> '';
update public.course_dates set yacht_slug = 'jeanneau-sun-odyssey-440-anda', boat = 'Anda, Jeanneau Sun Odyssey 440' where course_slug = 'international-flotilla-skipper' and boat <> '';
